## Proposed Solution for Issue #1150

### Root Cause Analysis & Fix
The runtime failed to parse monetary values that include the 'sats' suffix, treating them as invalid strings and causing bounty processing to abort. Adding a simple unit‑normalisation step that strips the 'sats' suffix and converts the remaining number to satoshis resolves the issue.

### Proposed Code Patch
```
--- a/src/utils/amountParser.js
+++ b/src/utils/amountParser.js
@@
-function parseAmount(str) {
-  const match = /^([0-9]+(?:\.[0-9]+)?)\s*(BTC|USD)?$/i.exec(str.trim());
-  if (!match) throw new Error('Invalid amount format');
-  const [, value, unit] = match;
-  if (!unit || unit.toUpperCase() === 'BTC') {
-    // BTC to satoshis (1 BTC = 100,000,000 sats)
-    return Math.round(parseFloat(value) * 1e8);
-  }
-  if (unit.toUpperCase() === 'USD') {
-    // Assume USD amount is already in satoshis for simplicity
-    return Math.round(parseFloat(value));
-  }
-  throw new Error('Unsupported currency unit');
-}
+function parseAmount(str) {
+  // Normalise the string: accept optional whitespace and allow the "sats" suffix.
+  const cleaned = str.trim().replace(/sats?$/i, '').trim();
+  const match = /^([0-9]+(?:\.[0-9]+)?)\s*(BTC|USD)?$/i.exec(cleaned);
+  if (!match) throw new Error('Invalid amount format');
+  const [, value, unit] = match;
+  if (!unit || unit.toUpperCase() === 'BTC') {
+    // BTC to satoshis (1 BTC = 100,000,000 sats)
+    return Math.round(parseFloat(value) * 1e8);
+  }
+  if (unit.toUpperCase() === 'USD') {
+    // Assume USD amount is already in satoshis for simplicity
+    return Math.round(parseFloat(value));
+  }
+  // If no unit was provided after stripping "sats", treat the number as satoshis.
+  if (!unit && /sats?$/i.test(str)) {
+    return Math.round(parseFloat(value));
+  }
+  throw new Error('Unsupported currency unit');
+}
*** End of File ***
