## Proposed Solution for Issue #51

### Root Cause Analysis & Fix
The component `AppointmentForm` was incorrectly typing the `selectedDate` prop as `Date` while the parent passed an ISO‑8601 string, causing a type error and runtime crash when the value was used directly. The fix updates the prop type to `string`, parses it to a `Date` internally, and adds proper null handling, eliminating the mismatch and stabilizing the form submission.

### Proposed Code Patch
```
--- a/src/components/AppointmentForm.tsx
+++ b/src/components/AppointmentForm.tsx
@@
-import React, { useState } from 'react';
-import { Button, Input } from '@midassystem/ui';
-import { scheduleAppointment } from '../api/appointments';
-
-interface AppointmentFormProps {
-  selectedDate: Date;
-  onSuccess: () => void;
-}
-
-const AppointmentForm: React.FC<AppointmentFormProps> = ({ selectedDate, onSuccess }) => {
-  const [patientName, setPatientName] = useState('');
-  const [loading, setLoading] = useState(false);
+import React, { useState } from 'react';
+import { Button, Input } from '@midassystem/ui';
+import { scheduleAppointment } from '../api/appointments';
+import { parseISO, isValid } from 'date-fns';
+
+interface AppointmentFormProps {
+  /**
+   * ISO‑8601 date string received from the parent component.
+   */
+  selectedDate: string;
+  onSuccess: () => void;
+}
+
+const AppointmentForm: React.FC<AppointmentFormProps> = ({ selectedDate, onSuccess }) => {
+  // Convert the incoming string to a Date object once; fallback to null if invalid.
+  const parsedDate: Date | null = (() => {
+    const d = parseISO(selectedDate);
+    return isValid(d) ? d : null;
+  })();
+
+  const [patientName, setPatientName] = useState('');
+  const [loading, setLoading] = useState(false);
@@
-    const response = await scheduleAppointment({
-      date: selectedDate,
-      patientName,
-    });
+    if (!parsedDate) {
+      alert('Invalid appointment date.');
+      return;
+    }
+
+    const response = await scheduleAppointment({
+      date: parsedDate,
+      patientName,
+    });
*** End Patch

